    public static readonly Quote[] Quotes = new Quote[]
    {
        new Quote { Id = "https://pt.wikiquote.org/wiki/Denise_C%C3%A9spedes", Text = "O book não e obrigatório. Antes de você fazer um, a Ford aconselha que vá a uma agência ver se tem condições de ser modelo. Aí sim, você terá que fazer um book.", Author = "Denise Céspedes" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Fernando_Fern%C3%A1n_G%C3%B3mez", Text = "O jornalista deve escrever em alta velocidade porque se não correr o risco de que, ao chegar à última linha, a primeira não seja mais atual.", Author = "Fernando Fernán Gómez" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Saw", Text = "Sim, estou doente, oficial. Doente da doença que lá dentro me come por fora. Farto das pessoas que não apreciam suas bênçãos. Farto das pessoas que escarnecem o sofrimento dos outros. Estou farto de tudo!", Author = "Saw" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Professor", Text = "Um professor sempre afeta a eternidade. Ele nunca saberá onde sua influência termina.", Author = "Professor" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Joseph_Theodorus_Suwatan", Text = "A cruz é o símbolo destes dias. A cruz foi peregrina e passou de mão em mão, viajando pelas paróquias da diocese de Manado.", Author = "Joseph Theodorus Suwatan" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Augusto_Trujillo_Arango", Text = "Acredito que a Igreja não é formada apenas por bispos e sacerdotes mas sim é comunhão de irmãos, de maneira em que os laicos também devem participar, isso sim, respeitando o espaço de cada um. Hoje em dia a Nova Evangelização está orientada a preparar às pessoas para serem verdadeiros cristãos.", Author = "Augusto Trujillo Arango" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Richard_Carlile", Text = "A maçonaria da Grande Loja dos dias de hoje é inteiramente judaica.", Author = "Richard Carlile" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Charles_Baudelaire", Text = "A Admiração começa onde acaba a compreensão.", Author = "Charles Baudelaire" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Ben_Carson", Text = "Então depois de um tempo, se as pessoas não aceitarem suas desculpas, você para de procurar por elas.", Author = "Ben Carson" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Carlos_Amigo_Vallejo", Text = "Dizem você esqueça a Deus e seja feliz, quando em realidade terei que pôr se quiser você ser feliz olhe a Deus.", Author = "Carlos Amigo Vallejo" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Paulo_Renato_Souza", Text = "Da próxima vez que tiver manifestação, também vou levar ovos.", Author = "Paulo Renato Souza" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Elizabeth_Bowen", Text = "O destino não é uma águia, ele rasteja como um rato.", Author = "Elizabeth Bowen" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/J%C3%B4_Soares", Text = "É uma decisão de lado a lado, e depois, a gula é um pecado (risos).", Author = "Jô Soares" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Watchmen", Text = "A imundície de todo sexo e matança vai espumar até a cintura e os políticos e as putas vão olhar para cima gritando 'Salve-nos!, e eu vou olhar para baixo e sussurrar 'Não'.", Author = "Watchmen" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Amblyopsis_hoosieri", Text = "Evoluíram com estas diferenças subtis na arquitetura genética por detrás da sua cegueira. Há um gene chamado rodopsina que é super crítico para a visão. Nós temo-lo e estas espécies também o têm, exceto uma espécie que perdeu todas as funções desse gene e a outra mantém-no.", Author = "Amblyopsis hoosieri" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Len_Deighton", Text = "A tragédia do casamento é que, enquanto todas as mulheres se casam pensando que seu homem irá mudar, todos os homens se casam pensando que sua mulher nunca mudará. Ambos invariavelmente se desapontam.", Author = "Len Deighton" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/John_Woo", Text = "Meus filhos preferem os filmes de John Woo.", Author = "John Woo" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/George_Herbert", Text = "Uma espada obriga a outra a ficar na bainha.", Author = "George Herbert" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Mortimer_Adler", Text = "Enquanto existem limites para o crescimento do corpo, a mente, ao contrário do corpo, pode crescer a cada ano de nossas vidas.", Author = "Mortimer Adler" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Adriano_Tomasi_Travaglia", Text = "Como podemos nós olhar a este rosto sagrado se não defendermos a vida, se aos anciões os deixamos expulsos em um asilo ou pior ainda nas ruas pedindo esmola?, que sociedade estamos construindo?", Author = "Adriano Tomasi Travaglia" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Charlton_Heston", Text = "Minhas primeiras cópias de Ilha de Tesouro e Huckleberry Finn ainda têm algumas agulhas de azul-abeto disperso nas páginas. Eles ainda tem aroma de Natal.", Author = "Charlton Heston" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Miro_Teixeira", Text = "O Rio tem uma administração Helena Rubinstein, de maquiagem.", Author = "Miro Teixeira" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/George_Jean_Nathan", Text = "Bebo para tornar as outras pessoas interessantes.", Author = "George Jean Nathan" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Dr._Seuss", Text = "Se você tem cérebro e sapatos nos pés, e o caminho não for agradável, vá por outro que julgar melhor.", Author = "Dr. Seuss" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/George_Eliot", Text = "Ninguém pode ser sábio de estômago vazio.", Author = "George Eliot" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Thomas_Paine", Text = "A minha pátria é o mundo, e a minha religião a prática do bem.", Author = "Thomas Paine" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/George_Vance_Murry", Text = "A tradição de nosso país de não estabelecer uma religião não significa que os governos possam negar outros benefícios permitidos com base em um estado religioso.", Author = "George Vance Murry" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Honor%C3%A9_de_Balzac", Text = "Há, em certas cidades de província, casas cuja vista inspira uma melancolia igual à que provocam os claustros mais sombrios, as charnecas mais desoladas ou as ruínas mais tristes.", Author = "Honoré de Balzac" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Peter_Kwasniewski", Text = "Se um sacramento deve ser cancelado, claramente uma pena ou uma restrição ao livre exercício de direitos, então tem que ter sido expressamente cancelado. Mas Traditionis custodes não fez isso.", Author = "Peter Kwasniewski" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Robert_Flaherty", Text = "Às vezes você precisa mentir. Freqüentemente você tem que distorcer uma coisa para captar seu espírito verdadeiro", Author = "Robert Flaherty" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Beatriz_Segall", Text = "O cinema brasileiro ficou muito voltado para as favelas, pobreza. E as pessoas acham que tenho cara de grã-fina", Author = "Beatriz Segall" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Harold_Wilson", Text = "Aquele que rejeita a mudança é o arquiteto da decadência. A única instituição humana que rejeita o progresso é o cemitério.", Author = "Harold Wilson" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Jos%C3%A9_Moreira_de_Melo", Text = "As redes sociais são o fruto da interação humana, mas, por sua vez, dão formas novas às dinâmicas da comunicação que cria relações; por isso, uma solícita compreensão por este ambiente é o pré-requisito para uma presença significativa dentro dele.", Author = "José Moreira de Melo" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Louis_Lecoin", Text = "Louis Lecoin, que foi descrito como o mais pacifista militante da França, morreu hoje em um hospital no subúrbio de Pavilions-Sous-Bois após uma cirurgia. Ele tinha 83 anos.", Author = "Louis Lecoin" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Trilha_Sonora_do_Gueto", Text = "Se vida loka é né Jão não é fácil não às vezes na Diogo si pá até na Fundão que tem tô enquadrado com a mão pro alto gambé ainda vem fala que eu so forgado.", Author = "Trilha Sonora do Gueto" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Yayoi_Kusama", Text = "Nossa terra é só uma bola entre um milhão de estrelas no cosmos. As bolinhas são um caminho para o infinito. Quando obliteramos a natureza e nosso corpo com bolinhas, tornamo-nos parte da unidade de nosso ambiente.", Author = "Yayoi Kusama" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Alfredo_V%C3%ADctor_Petit_Vergel", Text = "A situação do catolicismo em Cuba está igual a sempre. Não acredito que a situação do catolicismo tenha variado. 80 por cento dos 11 milhões de habitantes se dizem católicos, mas isso não significa que atuem como tal.", Author = "Alfredo Víctor Petit Vergel" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Joel_Waweru_Mwangi", Text = "Estamos desolados pelo que está acontecendo, mas queremos lançar um apelo aos nossos irmãos e irmãs cristãos para trabalhar para manter a paz.", Author = "Joel Waweru Mwangi" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/J%C3%BAlio_Duarte_Langa", Text = "Sou filho da Igreja e tudo o que me pedirem eu farei.", Author = "Júlio Duarte Langa" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Livro_de_Ezequiel", Text = "E sabereis que eu sou o Senhor, porque não andastes nos meus estatutos, nem cumpristes os meus juízos; antes fizestes conforme o juízo dos gentios que estão ao redor de vós.", Author = "Livro de Ezequiel" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Rudi_V%C3%B6ller", Text = "Você se senta confortavelmente aqui solto aqui em sua cadeira, depois de ter tomado três cervejas de trigo fica bêbado e relaxado.", Author = "Rudi Völler" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Autoridade", Text = "As mais soberanas funções do poder não gozam da sua soberania senão nos limites da competência em que as leis a circunscreveram. Excedida a competência, para logo cessa o benefício da soberania o caráter de autoridade juridicamente insindicável dos atos políticos do governo.", Author = "Autoridade" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Erro", Text = "A primeira glória é a reparação dos erros.", Author = "Erro" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/S%C3%A9bastien_Faure", Text = "As religiões são como pirilampos: só brilham na escuridão.", Author = "Sébastien Faure" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/George_MacDonald", Text = "A vida mede-se pela intensidade, não pelo movimento do relógio.", Author = "George MacDonald" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Anna_Sui", Text = "Anna foi uma das designers que ajudou a definir o que hoje entendemos como a Geração X.", Author = "Anna Sui" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Richard_Daniel_Alarc%C3%B3n_Urrutia", Text = "Estamos vivenciando muitos problemas, que agora se complicaram mais ainda. Já não é só o problema da saúde. Nem só o problema econômico. Não é só o problema social. Agora, é também político. Tudo o que estamos vivenciando, essa espécie de redemoinho que vai nos envolvendo, está provando a nossa fé.", Author = "Richard Daniel Alarcón Urrutia" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Daniela_Escobar", Text = "Ele nunca escolhe um bonitão para contracenar comigo", Author = "Daniela Escobar" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Avenged_Sevenfold", Text = "Time still turns the pages of the book it's burned", Author = "Avenged Sevenfold" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Jo%C3%A3o_Cabral_de_Melo_Neto", Text = "O meu nome é Severino, não tenho outro de pia, Como há muitos Severinos, que é santo de romaria, deram então de me chamar, Severino de Maria(...)", Author = "João Cabral de Melo Neto" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Andrew_Carnegie", Text = "Pense em si como um portal de sucesso sem paralelo. Uma vida inteira, gloriosa, se abre à sua frente. Consiga!", Author = "Andrew Carnegie" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Maguito_Vilela", Text = "É uma vergonha, uma esculhambação.", Author = "Maguito Vilela" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/James_Ira_Thomas_Jones", Text = "É maravilhoso como um piloto se torna animado depois que ele derruba sua primeira máquina; seu moral aumenta em pelo menos 100%.", Author = "James Ira Thomas Jones" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Batalha_de_Menin_Road_Ridge", Text = "Na frente do V Corps eles lançaram nada menos que seis contra-ataques... As perdas foram muito pesadas e capturamos mais de 1.300 prisioneiros.", Author = "Batalha de Menin Road Ridge" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Gil_Ant%C3%B4nio_Moreira", Text = "É Deus que está chegando.", Author = "Gil Antônio Moreira" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Oscar_Zeta_Acosta", Text = "A verdade é que a morte é um mistério para mim. Não tenho opinião formada sobre o assunto.", Author = "Oscar Zeta Acosta" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Emil_Lang", Text = "O Capitão Lang era uma pessoa matura, séria e calma no seu comportamento, contudo enérgico quando havia necessidade.", Author = "Emil Lang" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Soane_Lilo_Foliaki", Text = "Este comportamento violento está em total desacordo com a fé cristã. Sinto-me especialmente amargurado pelo comportamento do nosso povo em relação à comunidade chinesa que ofereceu bons serviços à população de Tonga.", Author = "Soane Lilo Foliaki" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/James_Branch_Cabell", Text = "As pessoas se casam por uma série de outras razões e com resultados variáveis. Mas se casar por amor é atrair uma inevitável tragédia.", Author = "James Branch Cabell" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Pr%C3%ADncipe", Text = "Os príncipes me dão muito quando não me tiram nada e me fazem bem bastante quando não me fazem mal; é tudo o que lhes peço.", Author = "Príncipe" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Jardel", Text = "Clássico é clássico e vice-versa...", Author = "Jardel" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Carlos_Pena_Filho", Text = "Há vinte anos de sua partida do Recife (quem mora em Recife engana a morte), tem uma pára ou pré posteridade a conviver com ele, o que ele conseguiu sem pedir, sem banalizar-se. Antes, fazendo-se compeendido e amado por todo os tipos de leitores, dos eruditos aos populares.", Author = "Carlos Pena Filho" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/II_Macabeus", Text = "E mesmo se eu me livrasse agora dos castigos dos homens, não poderia escapar, nem vivo nem morto, das mãos do Todo-poderoso.", Author = "II Macabeus" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Ernane_Galv%C3%AAas", Text = "Taxa de risco todos temos nas ruas do Rio. Num prédio público com autoridades bancárias, a taxa sobe.", Author = "Ernane Galvêas" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Emilio_Carlos_Berlie_Belaunzar%C3%A1n", Text = "É um sinal de comunhão com o Papa e a resposta às necessidades dos irmãos mais pobres.", Author = "Emilio Carlos Berlie Belaunzarán" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Viviane_Ara%C3%BAjo", Text = "Coloquei silicone em São Paulo", Author = "Viviane Araújo" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Peter_Ackroyd", Text = "O cheiro da biblioteca era sempre o mesmo – o odor de mofo de roupas velhas misturado ao cheiro mais forte de corpos sujos, criando o que o bibliotecário-chefe certa vez descreveu como o vapor da sopa social.", Author = "Peter Ackroyd" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Cyprian_Kizito_Lwanga", Text = "Como uma confederação, partilhamos valores e princípios comuns, respeitamos a dignidade do ser humano, acreditamos na solidariedade e na partilha, dedicamo-nos e estamos convencidos de que a subsidiariedade é a chave para uma cooperação harmónica entre os parceiros.", Author = "Cyprian Kizito Lwanga" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Pearl_S._Buck", Text = "Muitas pessoas perdem as pequenas alegrias enquanto aguardam a grande felicidade.", Author = "Pearl S. Buck" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Zen%C3%A3o_de_C%C3%ADtio", Text = "A natureza deu-nos somente uma boca, mas duas orelhas, de modo que nós devemos falar menos e escutar mais.", Author = "Zenão de Cítio" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Bob_Dylan", Text = "Sempre fui atraído por certo tipo de mulher. É a voz, mais do que qualquer coisa. Ouço primeiro a voz.", Author = "Bob Dylan" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Raul_Seixas", Text = "Eu prefiro ser essa metamorfose ambulante do que ter aquela velha opinião formada sobre tudo.", Author = "Raul Seixas" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Juan_Bautista_Alberdi", Text = "A onipotência do Estado é a negação da liberdade individual.", Author = "Juan Bautista Alberdi" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/M%C3%A1rcio_Vassallo", Text = "Tudo o que inspira a minha vida me move para escrever, e tudo o que me move para escrever inspira a minha vida. Eu poderia ser um leitor apaixonado e nunca me tornar escritor, claro. Mas não escreveria nunca, se não fosse um leitor apaixonado.", Author = "Márcio Vassallo" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Stendhal", Text = "Podemos conhecer tudo, salvo a nós próprios.", Author = "Stendhal" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Joyce_Carol_Oates", Text = "Ela passava por inteligente. Mas o que fazer da inteligência, como servir-se dela?.", Author = "Joyce Carol Oates" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Vladimir_Mayakovsky", Text = "Dizem que em algum lugar, parece que no Brasil, existe um homem feliz.", Author = "Vladimir Mayakovsky" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Fran%C3%A7ois_de_La_Rochefoucauld", Text = "A verdadeira coragem está em fazermos sem testemunha o que seríamos capazes de fazer diante de todo mundo.", Author = "François de La Rochefoucauld" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Max_Weber", Text = "Regra é, em primeiro lugar gestão da vida quotidiana.", Author = "Max Weber" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Francesco_Totti", Text = "O melhor modo de pedir desculpa, é dirigir-se apenas a quem pode perdoar. E é por isso que senti a necessidade de presentear Nossa Senhora do Divino Amor com a minha camiseta. Entrego-me a ela e sinto-me em paz com Deus e com os o homens.", Author = "Francesco Totti" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/The_Beatles", Text = "Não gostamos do som de vocês. Além disso, conjuntos de guitarristas não têm futuro.", Author = "The Beatles" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Jane_Fonda", Text = "Certa noite, ele trouxe outra mulher para nossa cama e eu topei. Sou muito competitiva e, afinal, eram os anos 60.", Author = "Jane Fonda" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Victor_Civita", Text = "NÃO é a mais fácil e cômoda palavra que existe. Se alguém diz não, os problemas acabaram. Os problemas realmente começam quando você diz SIM.", Author = "Victor Civita" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Charles_Caleb_Colton", Text = "Os excessos de nossa mocidade são saques sobre a nossa velhice, pagáveis com juros trinta anos depois.", Author = "Charles Caleb Colton" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/John_Green", Text = "François Rabelais. Era poeta. Suas últimas palavras foram: Saio em busca de um Grande Talvez. é por isso que estou indo embora. Para não ter de esperar a morte para procurar o Grande Talvez.", Author = "John Green" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/George_Harrison", Text = "Se soubéssemos que íamos ser os Beatles, tinhamo-nos esforçado mais.", Author = "George Harrison" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Robert_Quillen", Text = "Um debate é uma troca de conhecimentos, uma discussão é uma troca de ignorâncias.", Author = "Robert Quillen" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Erica_Jong", Text = "Todos são talentosos. Difícil é ter coragem de seguir pelo caminho sombrio através do qual o talento guia.", Author = "Erica Jong" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Giovanni_Tani", Text = "É importante reconhecer que além de escutar-se a si mesmo, é necessário confiar-se à Igreja, à ajuda do pai espiritual, quer dizer a quem está em capacidade de indicar de maneira mais objetiva o caminho por onde avançar.", Author = "Giovanni Tani" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Guillermo_Rodr%C3%ADguez_Melgarejo", Text = "Uma missão de caráter permanente, a fim de que os vínculos com as famílias se fortaleçam, tornando-se um espírito de respeito e gradualidade pedagógica.", Author = "Guillermo Rodríguez Melgarejo" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Ant%C3%B4nio_Delfim_Netto", Text = "O capital é como água. Sempre flui por onde encontra menos obstáculos.", Author = "Antônio Delfim Netto" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Luis_Alberto_de_Abreu", Text = "As forças irracionais estão presentes de maneira forte em nossa sociedade e cabe ao artista exteriorizar isso e erguer, inclusive, anteparos às forças obscurantistas.", Author = "Luis Alberto de Abreu" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Brooke_Shields", Text = "Estou pronta. Isso não me assusta", Author = "Brooke Shields" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Asp%C3%A1sia_Camargo", Text = "O Malan manda em mim, mas o presidente manda em todos.", Author = "Aspásia Camargo" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Wanessa_Camargo", Text = "Marcus soube que haveria uma apresentação de abertura, mandou meu material para a equipe dela e fui escolhida. Não teve nenhuma mutreta, como alguns disseram. Passei por uma seleção e me escolheram.", Author = "Wanessa Camargo" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Regiane_Alves", Text = "Nunca soube direito o que é namorar", Author = "Regiane Alves" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Jos%C3%A9_Luis_Lacunza_Maestroju%C3%A1n", Text = "Lembremo-nos bem: não existem corruptos sem corruptores, é claro, mas é difícil. Se prendemos os corruptos e os corruptores ficam livres, a situação continua.", Author = "José Luis Lacunza Maestrojuán" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Kim_Soo-nyung", Text = "O tiro com arco dá a você convicção. As pessoas precisam de convicção o tempo todo: para comer bem, para fazer qualquer coisa. Eu diria que o tiro com arco é o melhor esporte para uma ótima vida.", Author = "Kim Soo-nyung" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Cillian_Murphy", Text = "Se você se comporta como uma celebridade, em seguida, as pessoas vão tratá-lo como uma celebridade, se não, eles não a tratam assim. Também não há muito para escrever sobre mim nos tablóides.", Author = "Cillian Murphy" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Rakim", Text = "Planeta Terra era o meu lugar de nascimento, nascido para ser o único controlador do universo, além da parte do mapa que eu bati em primeiro lugar.", Author = "Rakim" }
    };
}